using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class HeldBallChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void Verify(Action<CreatureHybrid,BeachBall> capture=null){
  var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var ball=slice.GetComponentsInChildren<BeachBall>().First();var mind=god.GetComponent<CreatureCuriosity>();var nav=god.GetComponent<IslandNavigator>();var item=ball.GetComponent<CarryItem>();var hands=(CarryItem[])typeof(QuestSlice).GetField("held",F).GetValue(slice);Check(hands.All(h=>h==null),"Release player items");var field=typeof(QuestSlice).GetField("state",F);var original=field.GetValue(slice);var world=slice.GetComponentInChildren<VillageResources>();var people=world.Gatherers;var positions=people.Select(p=>p.transform.position).ToArray();var held=people.Select(p=>p.GetComponent<CarryItem>().held).ToArray();var gp=god.transform.position;var gr=god.transform.rotation;var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);float timeScale=Time.timeScale;Time.timeScale=0;
  god.Interrupt("Held toy QA");var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,hunger=.1f,water=100,crops=100};test.Hybrid.time=200;test.Building.observed=15;field.SetValue(slice,test);world.ResetWorld();god.NewSeason();ball.ResetWorld();slice.SetSanctuaryOpen(false);var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Cancel();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.05f,false);
  float u=nav.world.Scale;var centre=nav.world.ProjectFoot(item.home,nav.profile);Vector3 direction=default;
  void Step(float dt=.05f,bool report=true){if(report)god.ReportHeldBall(hands[1],true);ball.Advance(dt,test.paused);god.Tick(dt);}
  void Begin(){god.Interrupt("Stage next held-ball bout");god.State.time+=13;god.ReportHeldBall(item,true);god.Perceive();god.Tick(.05f);Check(god.FollowingHeldBall&&god.Owner==CreatureHybrid.ActionOwner.Observe,"Utility did not choose held-ball investigation: "+god.Explanation);}
  try{
   foreach(var p in people){p.Cancel();p.GetComponent<VillagerSocial>().ResetTask();p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<VillagerBlockPlay>().ResetTask();p.GetComponent<CarryItem>().held=true;p.transform.position+=Vector3.up*u*600;}
   foreach(var a in cooldowns.Keys)a.cooldown=god.State.time+10000;
   god.transform.position=centre;nav.ResetRoute();Check((bool)typeof(QuestSlice).GetMethod("TryGrab",F).Invoke(slice,new object[]{1,item}),"Native player ball pickup failed");
   bool staged=false;for(int i=0;i<24;i++){direction=Quaternion.Euler(0,i*15,0)*Vector3.forward;god.transform.rotation=Quaternion.LookRotation(direction);item.transform.position=centre+(direction*24+Vector3.up*10)*u;Physics.SyncTransforms();god.ReportHeldBall(item,true);god.Perceive();var choices=(System.Collections.Generic.List<CreatureCandidate>)typeof(CreatureHybrid).GetField("candidates",F).GetValue(god);if(choices.Any(c=>c.target==ball.GetComponent<HybridTarget>().id&&c.action==CreatureAction.InvestigateObject&&c.feasible)){staged=true;break;}}Check(staged,"No safe visible held-ball fixture");
   god.ReportHeldBall(people[0].GetComponent<CarryItem>(),true);god.Perceive();Check(!((System.Collections.Generic.List<CreatureCandidate>)typeof(CreatureHybrid).GetField("candidates",F).GetValue(god)).Any(c=>c.target==ball.GetComponent<HybridTarget>().id&&c.action==CreatureAction.InvestigateObject),"Held villager fabricated ball invitation");
   int completions=test.Hybrid.Evidence.completedCreatureActions;Begin();var start=god.transform.position;for(int i=0;i<25;i++)Step();Check(Vector3.Distance(god.transform.position,start)>u*2&&god.FollowingHeldBall,"Held ball did not produce actual routed movement");Check(hands[1]==item&&item.held&&mind.Holding==null&&ball.Body.isKinematic&&!item.GetComponent<Collider>().enabled,"Creature stole or released player ball");Check(!test.Hybrid.receipt.eligible||test.Hybrid.receipt.completedAt<test.Hybrid.intention.startedAt,"Following fabricated a teachable completion");capture?.Invoke(god,ball);
   test.paused=true;string paused=JsonUtility.ToJson(test);var frozen=god.transform.position;Step(2);Check(JsonUtility.ToJson(test)==paused&&god.transform.position==frozen,"Pause advanced held-toy play");test.paused=false;
   var before=god.transform.position;item.transform.position+=direction*u*4;for(int i=0;i<20;i++)Step();Check(Vector3.Distance(before,god.transform.position)>u*.5f&&god.FollowingHeldBall,"Moving the held ball did not update the route");
   god.ReportHeldBall(null,false);Step(.05f,false);Check(!god.FollowingHeldBall&&item.held&&hands[1]==item,"Input loss retained pursuit or released player ownership");for(int i=0;i<15;i++)Step();Check(!god.FollowingHeldBall,"Cooldown failed to interrupt repetitive following");
   var owner=god.Owner;int ownedEvidence=test.Hybrid.intention.evidenceId;god.ReportHeldBall(item,true);Check(god.Owner==owner&&test.Hybrid.intention.evidenceId==ownedEvidence,"New hand cue preempted another action");
   Begin();Step(.4f,false);Check(!god.FollowingHeldBall,"Stale hand reports retained follow");
   Begin();for(int i=0;i<180&&god.FollowingHeldBall;i++)Step();Check(!god.FollowingHeldBall&&test.Hybrid.Evidence.completedCreatureActions==completions,"Follow monopolized movement or fabricated completed practice");
   Begin();var target=item.GetComponent<HybridTarget>();var evidence=test.Hybrid.intention.evidenceId;god.ReportHeldBall(item,true);Check(god.Owner==CreatureHybrid.ActionOwner.Observe&&test.Hybrid.intention.evidenceId==evidence,"Hand updates interrupted an owned action");
   typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);god.NewSeason();ball.ResetWorld();hands[1]=null;Check(test.Valid()&&!god.FollowingHeldBall,"Save/reload revived held pursuit");
   Check((bool)typeof(QuestSlice).GetMethod("TryGrab",F).Invoke(slice,new object[]{1,item}),"No hand for toss handoff");item.transform.position=god.transform.position+(direction*24+Vector3.up*10)*u;god.transform.rotation=Quaternion.LookRotation(direction);Begin();hands[1]=null;item.held=false;item.GetComponent<Collider>().enabled=true;item.transform.position=god.transform.position+(direction*18+Vector3.up*10)*u;Check(ball.PlayerToss(-direction*(8f/18)),"Native handoff toss refused");god.ReportHeldBall(null,false);god.Tick(.02f);Check(!god.FollowingHeldBall&&god.Owner==CreatureHybrid.ActionOwner.Curiosity&&mind.Current==CreatureCuriosity.Phase.CatchBall,"Following blocked native catch selection after release");
   Debug.Log("BWVR_HELD_BALL_PASS: native pickup; feasible utility investigation; actual routed approach and moving target; exclusive player carry; pause, input loss, stale reports, bounded duration/cooldown; no fabricated practice; native Save/Load");
  }finally{god.Interrupt("Held toy QA restore");if(hands[1]!=null){hands[1].held=false;hands[1].GetComponent<Collider>().enabled=true;hands[1]=null;}field.SetValue(slice,original);world.ResetWorld();god.NewSeason();ball.ResetWorld();god.transform.SetPositionAndRotation(gp,gr);nav.ResetRoute();for(int i=0;i<people.Length;i++){people[i].transform.position=positions[i];people[i].GetComponent<CarryItem>().held=held[i];}foreach(var pair in cooldowns)pair.Key.cooldown=pair.Value;Time.timeScale=timeScale;}
 }
}
}
